#!/usr/bin/env python3
"""Schema validator for audit-collector logs."""

import json
import sys
from pathlib import Path

SCHEMA = {
    "type": "object",
    "required": ["timestamp", "source", "event_type"],
    "properties": {
        "timestamp": {"type": "string", "format": "date-time"},
        "source": {"type": "string", "minLength": 1},
        "event_type": {"type": "string", "enum": ["access", "modify", "delete", "create"]},
        "user": {"type": "string"},
        "details": {"type": "object"},
    },
}


def validate_record(record: dict) -> list[str]:
    errors = []
    required = SCHEMA.get("required", [])
    for field in required:
        if field not in record:
            errors.append(f"missing required field: {field}")
    props = SCHEMA.get("properties", {})
    for key, val in record.items():
        if key not in props:
            continue
        prop = props[key]
        if prop.get("type") == "string" and not isinstance(val, str):
            errors.append(f"{key} must be string, got {type(val).__name__}")
        if prop.get("type") == "object" and not isinstance(val, dict):
            errors.append(f"{key} must be object, got {type(val).__name__}")
        if key == "event_type" and val not in prop.get("enum", []):
            errors.append(f"{key} must be one of {prop['enum']}, got {val}")
    return errors


def validate_logs(log_dir: Path) -> int:
    exit_code = 0
    for path in sorted(log_dir.glob("*.jsonl")):
        with path.open() as f:
            for lineno, line in enumerate(f, start=1):
                line = line.strip()
                if not line:
                    continue
                try:
                    record = json.loads(line)
                except json.JSONDecodeError as exc:
                    print(f"{path}:{lineno} JSON decode error: {exc}")
                    exit_code = 1
                    continue
                errors = validate_record(record)
                for err in errors:
                    print(f"{path}:{lineno} schema error: {err}")
                    exit_code = 1
    return exit_code


if __name__ == "__main__":
    log_dir = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("logs")
    sys.exit(validate_logs(log_dir))

package parsers

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"time"
)

// GitLabJobEvent represents a parsed GitLab job webhook payload.
type GitLabJobEvent struct {
	ObjectKind      string     `json:"object_kind"`
	BuildID         int64      `json:"build_id"`
	BuildName       string     `json:"build_name"`
	BuildStage      string     `json:"build_stage"`
	BuildStatus     string     `json:"build_status"`
	BuildCreatedAt  *time.Time `json:"build_created_at"`
	BuildStartedAt  *time.Time `json:"build_started_at"`
	BuildFinishedAt *time.Time `json:"build_finished_at"`
	ProjectID       int64      `json:"project_id"`
	ProjectName     string     `json:"project_name"`
	Duration        *float64   `json:"duration"`
	QueuedDuration  *float64   `json:"queued_duration"`
	Runner          *Runner    `json:"runner"`
	User            *User      `json:"user"`
	Commit          *Commit    `json:"commit"`
}

// Runner describes the CI runner that executed the job.
type Runner struct {
	ID          int64    `json:"id"`
	Description string   `json:"description"`
	Active      bool     `json:"active"`
	IsShared    bool     `json:"is_shared"`
	Tags        []string `json:"tags"`
}

// User describes the user that triggered the pipeline.
type User struct {
	ID    int64  `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// Commit describes the commit the job is running for.
type Commit struct {
	ID        string `json:"id"`
	Message   string `json:"message"`
	Timestamp string `json:"timestamp"`
	URL       string `json:"url"`
	Author    struct {
		Name  string `json:"name"`
		Email string `json:"email""`
	} `json:"author"`
}

// ParseGitLabJobEvents reads a JSONL stream of GitLab job events.
//
// Fix: uses pointer types (*time.Time, *float64) for fields that GitLab
// omits or sets to null while a job is still running (build_finished_at,
// duration, queued_duration).  Previously these were value types, which
// caused json.Unmarshal to error out on every running job and produced
// incomplete audit logs.
func ParseGitLabJobEvents(r io.Reader) ([]GitLabJobEvent, error) {
	var events []GitLabJobEvent
	scanner := bufio.NewScanner(r)
	const maxCapacity = 1024 * 1024 // 1 MiB line buffer for large trace payloads
	buf := make([]byte, maxCapacity)
	scanner.Buffer(buf, maxCapacity)

	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		var ev GitLabJobEvent
		if err := json.Unmarshal(line, &ev); err != nil {
			return nil, fmt.Errorf("unmarshal line: %w", err)
		}
		events = append(events, ev)
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan: %w", err)
	}
	return events, nil
}

// ParseGitLabJobEventsFile is a convenience wrapper around ParseGitLabJobEvents.
func ParseGitLabJobEventsFile(path string) ([]GitLabJobEvent, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	return ParseGitLabJobEvents(f)
}

