#!/usr/bin/env python3
"""Dataset statistics script for medical_abstracts_v1."""
import os
import re
from pathlib import Path

DATA_DIR = Path("/training-data/deepa-a1/corpora/medical_abstracts_v1")

def main():
    files = sorted(DATA_DIR.glob("*.txt"))
    total_files = len(files)
    total_words = 0
    total_chars = 0
    section_counts = {"Background": 0, "Methods": 0, "Results": 0, "Conclusions": 0}

    for f in files:
        text = f.read_text()
        total_words += len(text.split())
        total_chars += len(text)
        for section in section_counts:
            if section in text:
                section_counts[section] += 1

    avg_words = total_words / total_files if total_files else 0
    avg_chars = total_chars / total_files if total_files else 0

    report = f"""medical_abstracts_v1 dataset statistics
========================================
Generated: 2026-04-06
Runner: deepa.a1

Files:              {total_files}
Total words:        {total_words}
Total characters:   {total_chars}
Avg words/file:     {avg_words:.1f}
Avg characters/file: {avg_chars:.1f}

Section presence:
  Background:   {section_counts['Background']} / {total_files}
  Methods:      {section_counts['Methods']} / {total_files}
  Results:      {section_counts['Results']} / {total_files}
  Conclusions:  {section_counts['Conclusions']} / {total_files}
"""
    print(report)

if __name__ == "__main__":
    main()

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"math/rand"
	"net/http"
	"os"
	"strconv"
	"sync"
	"time"
)

// health_probe.go — debugging-oriented HTTP health probe for the eval-server.
//
// Design goals:
//   - Capture every request/response cycle with structured debug logs.
//   - Expose latency, retry count, body snapshots, and any non-2xx status.
//   - Support both one-shot and continuous (daemon) modes.
//   - Be runnable standalone so SRE can exec it during incidents.

var (
	// Tunables via environment variables.
	targetURL     = env("PROBE_URL", "http://eval-server:8080/health")
	probeTimeout  = envDuration("PROBE_TIMEOUT", 5*time.Second)
	probeInterval = envDuration("PROBE_INTERVAL", 10*time.Second)
	maxRetries    = envInt("PROBE_RETRIES", 3)
	retryDelay    = envDuration("PROBE_RETRY_DELAY", 2*time.Second)
	maxBodyBytes  = envInt("PROBE_MAX_BODY_BYTES", 4096)
	mode          = env("PROBE_MODE", "oneshot") // "oneshot" or "daemon"
	logJSON       = envBool("PROBE_LOG_JSON", true)
)

// ProbeResult is emitted as a structured log line for every attempt.
type ProbeResult struct {
	Timestamp   time.Time `json:"ts"`
	Attempt     int       `json:"attempt"`
	MaxAttempts int       `json:"max_attempts"`
	URL         string    `json:"url"`
	StatusCode  int       `json:"status_code"`
	LatencyMs   int64     `json:"latency_ms"`
	BodySnippet string    `json:"body_snippet,omitempty"`
	Error       string    `json:"error,omitempty"`
	Retryable   bool      `json:"retryable"`
}

func main() {
	if !logJSON {
		log.SetFlags(log.LstdFlags | log.Lmicroseconds)
	}

	switch mode {
	case "daemon":
		runDaemon()
	default:
		runOneShot()
	}
}

func runOneShot() {
	ctx, cancel := context.WithTimeout(context.Background(), probeTimeout*time.Duration(maxRetries+1))
	defer cancel()

	res, ok := probeWithRetries(ctx)
	if !ok {
		os.Exit(1)
	}
	_ = res
}

func runDaemon() {
	ticker := time.NewTicker(probeInterval)
	defer ticker.Stop()

	var wg sync.WaitGroup
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	for {
		select {
		case <-ticker.C:
			wg.Add(1)
			go func() {
				defer wg.Done()
				probeCtx, probeCancel := context.WithTimeout(ctx, probeTimeout*time.Duration(maxRetries+1))
				defer probeCancel()
				_, _ = probeWithRetries(probeCtx)
			}()
		}
	}
}

// probeWithRetries attempts the health endpoint up to maxRetries+1 times.
// It logs every attempt. Returns the final ProbeResult and true if any
// attempt succeeded with HTTP 2xx.
func probeWithRetries(ctx context.Context) (ProbeResult, bool) {
	var last ProbeResult
	for attempt := 1; attempt <= maxRetries+1; attempt++ {
		res := doProbe(ctx, attempt)
		emit(res)
		last = res

		if res.StatusCode >= 200 && res.StatusCode < 300 {
			return res, true
		}

		if attempt <= maxRetries {
			// Jittered backoff before retry.
			d := retryDelay + time.Duration(rand.Int63n(int64(retryDelay)))
			select {
			case <-time.After(d):
			case <-ctx.Done():
				last.Error = fmt.Sprintf("context cancelled during retry backoff: %v", ctx.Err())
				emit(last)
				return last, false
			}
		}
	}
	return last, false
}

// doProbe performs a single HTTP GET and returns a ProbeResult.
func doProbe(ctx context.Context, attempt int) ProbeResult {
	start := time.Now()
	res := ProbeResult{
		Timestamp:   start.UTC(),
		Attempt:     attempt,
		MaxAttempts: maxRetries + 1,
		URL:         targetURL,
	}

	reqCtx, cancel := context.WithTimeout(ctx, probeTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(reqCtx, http.MethodGet, targetURL, nil)
	if err != nil {
		res.Error = fmt.Sprintf("request construction failed: %v", err)
		res.Retryable = isRetryable(err)
		return res
	}
	req.Header.Set("X-Probe-Attempt", strconv.Itoa(attempt))
	req.Header.Set("Accept", "application/json")

	resp, err := http.DefaultClient.Do(req)
	res.LatencyMs = time.Since(start).Milliseconds()
	if err != nil {
		res.Error = fmt.Sprintf("request failed: %v", err)
		res.Retryable = isRetryable(err)
		return res
	}
	defer resp.Body.Close()

	res.StatusCode = resp.StatusCode
	res.Retryable = resp.StatusCode >= 500 || resp.StatusCode == 429

	// Snapshot a bounded prefix of the body for debugging.
	body, err := io.ReadAll(io.LimitReader(resp.Body, int64(maxBodyBytes)))
	if err != nil {
		res.Error = fmt.Sprintf("body read error: %v", err)
		return res
	}
	if len(body) > 0 {
		// JSON pretty-print if possible; otherwise raw string.
		var pretty map[string]interface{}
		if json.Unmarshal(body, &pretty) == nil {
			b, _ := json.Marshal(pretty)
			res.BodySnippet = string(b)
		} else {
			res.BodySnippet = string(body)
		}
	}

	return res
}

// emit logs a ProbeResult as a single JSON line.
func emit(r ProbeResult) {
	if logJSON {
		b, _ := json.Marshal(r)
		log.Println(string(b))
		return
	}
	log.Printf("probe attempt=%d/%d url=%s status=%d latency_ms=%d retryable=%t error=%q body=%q",
		r.Attempt, r.MaxAttempts, r.URL, r.StatusCode, r.LatencyMs, r.Retryable, r.Error, r.BodySnippet)
}

// isRetryable decides whether an error should trigger a retry.
// In production this can be expanded to inspect net.Error.Timeout(), etc.
func isRetryable(err error) bool {
	if err == nil {
		return false
	}
	// Conservative default: assume transient network errors are retryable.
	return true
}

// ----------------------------------------------------------------------
// Env helpers

func env(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

func envInt(key string, fallback int) int {
	if v := os.Getenv(key); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			return n
		}
	}
	return fallback
}

func envDuration(key string, fallback time.Duration) time.Duration {
	if v := os.Getenv(key); v != "" {
		if d, err := time.ParseDuration(v); err == nil {
			return d
		}
	}
	return fallback
}

func envBool(key string, fallback bool) bool {
	if v := os.Getenv(key); v != "" {
		if b, err := strconv.ParseBool(v); err == nil {
			return b
		}
	}
	return fallback
}
